components.css:
.ds-specimen { font-family: Avenir Next, PingFang SC, system-ui, sans-serif; color: var(--slate-12, #1c2024); }
.ds-learning-start-button{
  display: flex;
  justify-content: space-between;
  width: 100%;
  min-height: 52px;
  align-items: center;
  padding: 16px 20px;
  background: var(--iris-9, #5b5bd6);
  color: var(--iris-1, #fdfdff);
  border-radius: 6px;
  margin-top: 24px;
  font-size: 16px;
}
.ds-learning-start-button:hover{
  background: var(--iris-10, #5151cd);
}
.ds-specimen :focus-visible { outline: 2px solid var(--iris-8, #9b9ef0); outline-offset: 3px; }
@media (prefers-reduced-motion: reduce) { .ds-specimen * { animation: none !important; transition: none !important; } }

.ds-specimen { font-family: Avenir Next, PingFang SC, system-ui, sans-serif; color: var(--slate-12, #1c2024); }
.ds-learning-choices{
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 28px;
}
.ds-learning-choices button{
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 20px 16px;
  background: var(--iris-2, #f8f8ff);
  border: 0.5px solid var(--iris-7, #b8baf8);
  border-radius: 6px;
  color: var(--iris-12, #272962);
  font-size: 24px;
}
.ds-learning-choices button:hover{
  background: var(--iris-4, #e6e7ff);
}
.ds-learning-choices button.ds-is-correct{
  color: var(--teal-11, #008573);
  background: var(--teal-3, #e0f8f3);
  border-color: var(--teal-8, #53b9ab);
}
.ds-learning-choices button.ds-is-wrong{
  color: var(--ruby-11, #ca244d);
  background: var(--ruby-3, #feeaed);
  border-color: var(--ruby-8, #e592a3);
}
.ds-learning-choices{
  border: 0;
  padding: 0;
  min-width: 0;
}
.ds-specimen :focus-visible { outline: 2px solid var(--iris-8, #9b9ef0); outline-offset: 3px; }
@media (prefers-reduced-motion: reduce) { .ds-specimen * { animation: none !important; transition: none !important; } }

.ds-specimen { font-family: Avenir Next, PingFang SC, system-ui, sans-serif; color: var(--slate-12, #1c2024); }
.ds-g-search{
  flex-shrink: 0;
}
.ds-g-search{
  margin: 4px 16px 10px;
}
.ds-g-search input{
  width: 100%;
  min-height: 52px;
  border-radius: 6px;
  border: 0.5px solid var(--line);
  background: #fdfdff;
  padding: 0 16px;
  font-size: 12px;
  box-shadow: none;
}
.ds-g-search input{
  border-color: var(--line);
  background: var(--card);
}
.ds-specimen :focus-visible { outline: 2px solid var(--iris-8, #9b9ef0); outline-offset: 3px; }
@media (prefers-reduced-motion: reduce) { .ds-specimen * { animation: none !important; transition: none !important; } }

.ds-specimen { font-family: Avenir Next, PingFang SC, system-ui, sans-serif; color: var(--slate-12, #1c2024); }
.ds-learning-unit{
  border-top: 0.5px solid var(--slate-6, #d9d9e0);
}
.ds-learning-unit:last-of-type{
  border-bottom: 0.5px solid var(--slate-6, #d9d9e0);
}
.ds-learning-unit summary{
  display: flex;
  align-items: center;
  gap: 16px;
  min-height: 80px;
  cursor: pointer;
  list-style: none;
}
.ds-learning-unit summary::-webkit-details-marker{
  display: none;
}
.ds-learning-unit summary::after{
  content: "+";
  color: var(--slate-11, #60646c);
  font-size: 16px;
}
.ds-learning-unit[open] summary::after{
  content: "−";
}
.ds-learning-unit h3{
  font-size: 16px;
  font-weight: 600;
  flex: 1;
}
.ds-learning-unit summary > span{
  font-size: 12px;
  color: var(--slate-11, #60646c);
  font-variant-numeric: tabular-nums;
}
.ds-learning-unit ol{
  list-style: none;
  padding: 0 0 20px;
}
.ds-learning-unit li button{
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  min-height: 52px;
  text-align: left;
  padding: 12px;
  font-size: 16px;
  border-radius: 4px;
}
.ds-learning-unit li button:hover:not(:disabled){
  background: var(--slate-3, #f0f0f3);
}
.ds-learning-unit li button.ds-is-next{
  background: var(--iris-3, #f0f1fe);
  color: var(--iris-11, #5753c6);
}
.ds-learning-unit li button:disabled{
  color: var(--slate-11, #60646c);
  opacity: 1;
  cursor: default;
}
.ds-specimen :focus-visible { outline: 2px solid var(--iris-8, #9b9ef0); outline-offset: 3px; }
@media (prefers-reduced-motion: reduce) { .ds-specimen * { animation: none !important; transition: none !important; } }

.ds-specimen { font-family: Avenir Next, PingFang SC, system-ui, sans-serif; color: var(--slate-12, #1c2024); }
.ds-nav{
  flex-shrink: 0;
  height: calc(var(--nav-h, 68px) + env(safe-area-inset-bottom, 0px));
  padding-bottom: env(safe-area-inset-bottom, 0px);
  display: flex;
  z-index: 8;
}
.ds-nav button{
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.ds-nav svg{
  width: 26px;
  height: 26px;
}
.ds-nav{
  height: calc(72px + env(safe-area-inset-bottom, 0px));
  border-top: 0;
  background: var(--ink);
  box-shadow: none;
}
.ds-nav button{
  color: #adb5b2;
}
.ds-nav button.ds-on{
  color: var(--yellow);
}
.ds-nav button.ds-on::after{
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #ff977d;
  content: "";
}
.ds-nav button.ds-on .ds-icon{
  animation: none;
}
.ds-nav{
  position: relative;
  width: 100%;
  margin-top: auto;
  display: flex;
  justify-content: space-around;
  background: var(--slate-1, #fcfcfd);
  border-top: 0.5px solid var(--slate-6, #d9d9e0);
  padding: 10px 20px max(10px, env(safe-area-inset-bottom));
  height: auto;
  min-height: 72px;
  flex-shrink: 0;
  box-shadow: none;
}
.ds-nav button{
  color: var(--slate-11, #60646c);
  font-size: 12px;
  min-width: 60px;
  border-radius: 4px;
}
.ds-nav button.ds-on{
  color: var(--iris-11, #5753c6);
  background: var(--iris-3, #f0f1fe);
}
.ds-nav button.ds-on::after{
  display: none;
}
.ds-nav svg{
  width: 22px;
  height: 22px;
}
.ds-specimen :focus-visible { outline: 2px solid var(--iris-8, #9b9ef0); outline-offset: 3px; }
@media (prefers-reduced-motion: reduce) { .ds-specimen * { animation: none !important; transition: none !important; } }
